  '{"folder":"guide","category":"指南","tags":["guide","quickstart"],"reading_time":3,"template_id":"page_tpl_article"}', 'ver_art_hello_1', 'admin', CURRENT_TIMESTAMP, '2026-11-18 10:00:00'
