INSERT INTO article_versions (id, article_id, version_number, title, summary, content_raw, metadata_snapshot, commit_message, author_id) VALUES ('ver_art_hello_1', 'art_hello_walnut', 1, '欢迎使用 Walnut：5 分钟上手指南', '从零了解 Walnut CMS 的内容模型、Markdown 容器、TOC 目录与双向知识内链。', '欢迎使用 **Walnut CMS**！这是一篇开箱即用的交互式向导文章，你可以随时编辑它，或在后台按 `folder: guide` 一键清理所有示例内容。

[[tip: 示例目录约定：默认预置的向导文章与微内容统一归属 `guide` 目录，熟悉系统后可在文章/微内容列表按目录筛选并批量移入回收站。]]

## 1. 为什么采用微内核与混合数据模型

Walnut CMS 将核心内容拆分为三类互补实体：

- **文章 (Articles)**：承载结构化长文、Markdown 扩展容器、多版本快照与多语种互译。
- **页面 (Pages)**：通过可视化槽位（`header` / `main` / `sidebar` / `footer`）与 `@api:` 协议装配任意积木。
- **微内容 (Micros)**：无需标题与独立 URL 的轻量速记流，适合记录短想法与过程状态。

### 自动大纲与双向知识内链

右侧目录大纲会自动扫描正文中的 `H2` 与 `H3` 标题生成锚点导航。此外，你可以使用 `[[slug|显示标题]]` 建立知识双链——例如继续阅读下一篇指南：[[architecture-and-slots|页面装配、微内容与 @api: 数据直连]]。

## 2. 下一步操作清单

1. 进入控制台 **/admin** 修改站点名称、亮/暗主色与首页积木变体。
2. 访问 **/archive** 查看文章与无标题微内容在同一条时间线上的混排效果。
3. 访问 **/projects** 查看结构化数据集 `projects` 的动态展柜效果。', '{}', 'Initial starter guide', 'admin');

