  '{"folder":"guide","category":"Guide","tags":["guide","quickstart"],"reading_time":3,"template_id":"page_tpl_article"}', 'ver_art_hello_en_1', 'admin', CURRENT_TIMESTAMP, '2026-11-18 09:50:00'
);
INSERT INTO article_versions (id, article_id, version_number, title, summary, content_raw, metadata_snapshot, commit_message, author_id) VALUES ('ver_art_hello_en_1', 'art_hello_walnut_en', 1, 'Welcome to Walnut: 5-Minute Starter Guide', 'Quick introduction to Walnut articles, micros, slots, and @api: protocols.', 'Welcome to **Walnut CMS**! This starter guide demonstrates Markdown formatting, custom containers, TOC outlines, and bilingual translation groups.

[[tip: All starter guide items are tagged with `folder: guide` so you can filter and delete them cleanly once you are ready to publish your own site.]]

## 1. Core Building Blocks

- **Articles**: Long-form Markdown with version snapshots and translation links.
- **Pages**: Slot-based visual assembly powered by `@api:` data protocols.
- **Micros**: Untitled lightweight notes aggregated into feeds and timelines.

### Next Steps

Visit **/archive** to inspect mixed timeline aggregation via `@api:feed:`, or switch back to [[architecture-and-slots|Architecture & Slots]].', '{}', 'Initial EN guide', 'admin');

