  'art_arch_slots', 'site_default', 'architecture-and-slots', 'zh-CN', NULL, 'published', 'public', 'guide', '页面装配、微内容与 @api: 数据直连', '深入理解可视化槽位、母版夹心装配与 @api: 动态数据源绑定。', '',
  '{"folder":"guide","category":"指南","tags":["guide","slots","api"],"reading_time":4,"template_id":"page_tpl_article"}', 'ver_art_arch_1', 'admin', CURRENT_TIMESTAMP, '2026-11-18 09:30:00'
);
INSERT INTO article_versions (id, article_id, version_number, title, summary, content_raw, metadata_snapshot, commit_message, author_id) VALUES ('ver_art_arch_1', 'art_arch_slots', 1, '页面装配、微内容与 @api: 数据直连', '深入理解可视化槽位、母版夹心装配与 @api: 动态数据源绑定。', '在 Walnut CMS 中，主题负责视觉样式与组件契约，页面负责装配具体积木与绑定业务数据。

[[tip: 回到第一篇上手指南：[[hello-walnut|欢迎使用 Walnut：5 分钟上手指南]]。]]

## 1. 槽位装配与母版夹心机制

主题骨架提供 `header:1`、`subnav:2`、`main`、`sidebar:3` 与 `footer:1` 五类插槽：

- **母版页 (`page_type = ''template''`)**：可在 `main` 槽位放置 `@slot:page_content` 占位符，参考 **/about** 页面。
- **单页覆盖规则**：固定配额槽位由母版先行入队，超出配额的积木会自动挂起但不丢失配置。

### 常用 `@api:` 动态数据协议

- `@api:articles:limit=6`：拉取最新已发布文章。
- `@api:micro:limit=6`：拉取最新微内容记录。
- `@api:dataset:schema=projects`：拉取指定 Schema 的结构化数据集条目。
- `@api:feed:types=article,micro&limit=20`：并发混排多类型内容并按 `created_at DESC` 统一排序。

## 2. 多站点隔离与静态资产

每个站点拥有独立的路由缓存表 `site_routes`、媒体资产与主题配置，支持在多域名之间隔离运行。', '{}', 'Initial architecture guide', 'admin');

